# Defining a tool the model is allowed to call.
tools = [{
    "type": "function",
    "function": {
        "name": "get_order",
        "description": "Look up an order by its ID for the current customer.",
        "parameters": {
            "type": "object",
            "properties": {
                "order_id": {"type": "string", "description": "The order ID"}
            },
            "required": ["order_id"]
        }
    }
}]

# The model outputs (as TEXT):
#   { "name": "get_order", "arguments": { "order_id": "12345" } }
# Your orchestrator then calls the REAL get_order("12345").

# VULNERABLE: trusts whatever the model sends, unlimited scope.
def get_order(order_id):
    return db.query(f"SELECT * FROM orders WHERE id = {order_id}")  # SQLi + no ownership check


# SECURE: parameterized, scoped to the logged-in user, validated.
def get_order(order_id, *, current_user_id):
    if not order_id.isdigit():
        raise ValueError("Invalid order id")
    return db.query(
        "SELECT * FROM orders WHERE id = %s AND customer_id = %s",
        (order_id, current_user_id),   # ownership enforced in CODE, not in the prompt
    )
